use vstd::prelude::*;

verus! {
    fn longest(strings: Vec<Vec<char>>) -> (result: Option<Vec<char>>)
        requires
            // The input list can be empty or contain sequences of characters
            true,
        ensures
            // If the input list is empty, the result is None
            strings.len() == 0 ==> result == None,
            // If the input list is not empty, the result is Some of the longest sequence
            strings.len() > 0 ==> 
                match result {
                    Some(ref seq) => {
                        let max_length = strings.iter().map(|s| s.len()).max().unwrap();
                        seq.len() == max_length && 
                        strings.iter().position(|s| s.len() == max_length) == Some(strings.iter().position(|s| s == seq).unwrap())
                    },
                    None => false,
                },
    {
        if strings.len() == 0 {
            return None;
        }

        let mut longest_seq: Option<Vec<char>> = None;
        let mut max_length: usize = 0;

        for (i, seq) in strings.iter().enumerate() {
            let current_length = seq.len();
            if current_length > max_length {
                longest_seq = Some(seq.clone());
                max_length = current_length;
            }
        }

        longest_seq
    }
}
